import { getAuthUserId } from "@convex-dev/auth/server";
import { mutation, query } from "./_generated/server";
import { v } from "convex/values";
import type { Id } from "./_generated/dataModel";
import { requireLocationAccess, requireLocationAdmin, requireLocationManager, requireSignedIn } from "./permissions";

const stores = [
  { name: "Blackpool North", shortName: "Blackpool" },
  { name: "Bolton", shortName: "Bolton" },
  { name: "Poulton-le-Fylde", shortName: "Poulton" },
  { name: "Rochdale", shortName: "Rochdale" },
];
const securityDefaults = ["Premises secure?", "Required security checks completed?", "Required security procedures understood and followed?"];
const openingDefaults = ["Food fridges operating correctly?", "Drinks fridges operating correctly?", "Food-preparation surfaces clean?", "Handwash soap available?", "Hot water available?", "Disposable hand-drying available?", "Food probe available and sanitised?", "Approved chemicals available?", "Allergen information available?", "Food correctly stored and labelled?", "No evidence of pest activity?", "Staff fit for work?"];
const closingDefaults = ["PM temperature checks completed?", "Expired or damaged food removed?", "Open food covered and labelled?", "Chilled food stored safely?", "Food-preparation areas cleaned?", "Equipment and utensils cleaned?", "Waste removed and bins controlled?", "Floors cleaned?", "Chemicals stored correctly?", "Outstanding issues handed over?"];
const equipmentCount = 4;
const wastageDefaults = ["Sausages", "Chicken Brioche", "Milk", "Bread"];
const cleaningDefaults = ["Food preparation surfaces", "Counters and service area", "Handles and touch points", "Floors", "Bins and waste area"];
const trainingDefaults = ["HOT & WHAT", "Allergen Guide", "Merrychef Training", "Panic Alarm"];

function localDateKey(timestamp: number, timezone: string) { return new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(timestamp)); }
function localWeekday(timestamp: number, timezone: string) { const label = new Intl.DateTimeFormat("en-US", { timeZone: timezone, weekday: "short" }).format(new Date(timestamp)); return ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(label) + 1; }
function nextAdditionalDue(frequency: "weekly" | "monthly" | "every_x_weeks" | "every_x_months" | "annual" | "one_off", interval = 1, from: number) { const date = new Date(from); if (frequency === "one_off") return from; if (frequency === "weekly") date.setDate(date.getDate() + 7); if (frequency === "monthly") date.setMonth(date.getMonth() + 1); if (frequency === "every_x_weeks") date.setDate(date.getDate() + 7 * Math.max(1, interval)); if (frequency === "every_x_months") date.setMonth(date.getMonth() + Math.max(1, interval)); if (frequency === "annual") date.setFullYear(date.getFullYear() + 1); return date.getTime(); }
async function signedIn(ctx: any) {
  const userId = await getAuthUserId(ctx);
  if (!userId) throw new Error("You must be signed in");
  return userId;
}
async function seedLocation(ctx: any, locationId: Id<"locations">, userId: Id<"users">) {
  const existingTeamMembers = await ctx.db.query("teamMembers").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingTeamMembers.length) { const user = await ctx.db.get(userId); await ctx.db.insert("teamMembers", { locationId, name: user?.name || user?.email || "Team member", active: true, createdAt: Date.now() }); }
  const existingEquipment = await ctx.db.query("equipment").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingEquipment.length) for (let number = 1; number <= equipmentCount; number++) await ctx.db.insert("equipment", { locationId, name: `Fridge ${number}`, type: "Food fridge", preferredTemperature: 5, maximumTemperature: 8, order: number - 1, active: true });
  for (const session of ["AM", "PM"] as const) {
    const existing = await ctx.db.query("securityQuestions").withIndex("by_location_session", (q: any) => q.eq("locationId", locationId).eq("session", session)).collect();
    if (!existing.length) for (const [order, question] of securityDefaults.entries()) await ctx.db.insert("securityQuestions", { locationId, session, question, order, active: true });
  }
  for (const [checklist, defaults] of [["opening", openingDefaults], ["closing", closingDefaults]] as const) {
    const existing = await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", (q: any) => q.eq("locationId", locationId).eq("checklist", checklist)).collect();
    if (!existing.length) for (const [order, question] of defaults.entries()) await ctx.db.insert("checklistQuestions", { locationId, checklist, question, order, active: true });
  }
  const existingWastage = await ctx.db.query("wastageItems").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingWastage.length) for (const [order, name] of wastageDefaults.entries()) await ctx.db.insert("wastageItems", { locationId, name, order, active: true });
  const existingCleaning = await ctx.db.query("cleaningTasks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingCleaning.length) for (const [order, name] of cleaningDefaults.entries()) await ctx.db.insert("cleaningTasks", { locationId, name, frequency: "daily", weekdays: [], order, active: true });
  const existingTraining = await ctx.db.query("trainingRequirements").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingTraining.length) for (const [order, title] of trainingDefaults.entries()) await ctx.db.insert("trainingRequirements", { locationId, title, order, active: true });
}

export const dashboard = query({
  args: { locationId: v.optional(v.id("locations")) },
  handler: async (ctx, args) => {
    const userId = await requireSignedIn(ctx);
    const memberships = await ctx.db.query("memberships").withIndex("by_user", q => q.eq("userId", userId)).collect();
    const locationId = args.locationId ?? memberships[0]?.locationId;
    if (!locationId) return null;
    const membership = await requireLocationAccess(ctx, locationId);
    const location = await ctx.db.get(locationId);
    if (!location) return null;
    const equipment = (await ctx.db.query("equipment").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order);
    const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
    const todayKey = localDateKey(Date.now(), location.timezone);
    const rounds = (await ctx.db.query("temperatureRounds").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(round => localDateKey(round.startedAt, location.timezone) === todayKey);
    const readings = (await ctx.db.query("temperatureReadings").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(reading => localDateKey(reading.createdAt, location.timezone) === todayKey);
    const issues = await ctx.db.query("issues").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
    const foodChecks = await Promise.all((await ctx.db.query("foodChecks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(check => localDateKey(check.createdAt, location.timezone) === todayKey).map(async check => ({ ...check, teamMemberName: check.teamMemberId ? (await ctx.db.get(check.teamMemberId))?.name : undefined })));
    const organisation = await ctx.db.get(location.organisationId);
    const probeProducts = organisation ? (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", organisation._id)).collect()).filter(product => product.active && product.locationIds.includes(locationId)).sort((a, b) => (a.order ?? 0) - (b.order ?? 0)) : [];
    const openingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "opening")).collect()).filter(question => question.active);
    const closingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "closing")).collect()).filter(question => question.active);
    const openingResponses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "opening")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey);
    const closingResponses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "closing")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey);
    const checklistSignOffs = await Promise.all((await ctx.db.query("checklistSignOffs").withIndex("by_location_checklist_date", q => q.eq("locationId", locationId).eq("checklist", "opening").eq("dateKey", todayKey)).collect()).concat(await ctx.db.query("checklistSignOffs").withIndex("by_location_checklist_date", q => q.eq("locationId", locationId).eq("checklist", "closing").eq("dateKey", todayKey)).collect()).map(async signOff => ({ ...signOff, teamMemberName: (await ctx.db.get(signOff.teamMemberId))?.name })));
    const securitySignOffs = await Promise.all((await ctx.db.query("securitySignOffs").withIndex("by_location_session_date", q => q.eq("locationId", locationId).eq("session", "AM").eq("dateKey", todayKey)).collect()).concat(await ctx.db.query("securitySignOffs").withIndex("by_location_session_date", q => q.eq("locationId", locationId).eq("session", "PM").eq("dateKey", todayKey)).collect()).map(async signOff => ({ ...signOff, teamMemberName: (await ctx.db.get(signOff.teamMemberId))?.name })));
    const security = { AM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "AM")).collect()).filter(question => question.active).sort((a, b) => a.order - b.order), PM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "PM")).collect()).filter(question => question.active).sort((a, b) => a.order - b.order) };
    const securityResponses = { AM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "AM")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey), PM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "PM")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey) };
    const wastageItems = (await ctx.db.query("wastageItems").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order);
    const wastageRecords = await Promise.all((await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(record => localDateKey(record.createdAt, location.timezone) === todayKey).map(async record => ({ ...record, teamMemberName: record.teamMemberId ? (await ctx.db.get(record.teamMemberId))?.name : undefined })));
    const weekday = localWeekday(Date.now(), location.timezone);
    const dateKey = todayKey;
    const cleaningTasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(task => task.active && (task.frequency === "after_use" || task.frequency === "daily" || (task.frequency === "weekly" && weekday === 1) || (task.frequency === "specific_days" && task.weekdays.includes(weekday)))).sort((a, b) => a.order - b.order);
    const cleaningCompletions = await Promise.all((await ctx.db.query("cleaningCompletions").withIndex("by_location_date", q => q.eq("locationId", locationId).eq("dateKey", dateKey)).collect()).map(async completion => ({ ...completion, teamMemberName: completion.teamMemberId ? (await ctx.db.get(completion.teamMemberId))?.name : undefined })));
    const teamMembers = (await ctx.db.query("teamMembers").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(member => member.active);
    const trainingRequirements = await Promise.all((await ctx.db.query("trainingRequirements").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(requirement => requirement.active).sort((a, b) => a.order - b.order).map(async requirement => ({ ...requirement, documentUrl: requirement.documentStorageId ? await ctx.storage.getUrl(requirement.documentStorageId) : null })));
    const trainingCompletions = await Promise.all((await ctx.db.query("trainingCompletions").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).map(async completion => ({ ...completion, teamMemberName: (await ctx.db.get(completion.teamMemberId))?.name, requirementTitle: (await ctx.db.get(completion.requirementId))?.title })));
    const additionalRequirements = (await ctx.db.query("additionalRequirements").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(requirement => requirement.active && requirement.nextDueAt <= Date.now()).sort((a, b) => a.order - b.order);
    const additionalCompletions = await Promise.all((await ctx.db.query("additionalCompletions").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).map(async completion => ({ ...completion, teamMemberName: (await ctx.db.get(completion.teamMemberId))?.name, requirementTitle: (await ctx.db.get(completion.requirementId))?.title, documentUrl: completion.documentStorageId ? await ctx.storage.getUrl(completion.documentStorageId) : null })));
    const issueUpdates = await ctx.db.query("issueUpdates").withIndex("by_location", q => q.eq("locationId", locationId)).collect();
    const issuesWithUpdates = await Promise.all(issues.map(async issue => ({ ...issue, createdByName: (await ctx.db.get(issue.createdBy))?.name ?? "Staff member", resolvedByName: issue.resolvedBy ? (await ctx.db.get(issue.resolvedBy))?.name ?? "Manager" : undefined, updates: await Promise.all(issueUpdates.filter(update => update.issueId === issue._id).sort((a, b) => a.createdAt - b.createdAt).map(async update => ({ ...update, createdByName: (await ctx.db.get(update.createdBy))?.name ?? "Staff member" }))) })));
    return { location, equipment, tasks, rounds, readings, issues: issuesWithUpdates, foodChecks, probeProducts, security, securityResponses, checklistSignOffs, securitySignOffs, wastageItems, wastageRecords, cleaningTasks, cleaningCompletions, teamMembers, trainingRequirements, trainingCompletions, additionalRequirements, additionalCompletions, checklists: { opening: { questions: openingQuestions.sort((a, b) => a.order - b.order), responses: openingResponses }, closing: { questions: closingQuestions.sort((a, b) => a.order - b.order), responses: closingResponses } }, role: membership.role };
  },
});

export const team = query({ args: { locationId: v.id("locations") }, handler: async (ctx, args) => { await requireLocationManager(ctx, args.locationId); const members = (await ctx.db.query("teamMembers").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(member => member.active); return { members }; } });
export const addTeamMemberName = mutation({ args: { locationId: v.id("locations"), name: v.string() }, handler: async (ctx, args) => { await requireLocationManager(ctx, args.locationId); return await ctx.db.insert("teamMembers", { locationId: args.locationId, name: args.name.trim(), active: true, createdAt: Date.now() }); } });
export const updateTeamMemberName = mutation({ args: { memberId: v.id("teamMembers"), name: v.string() }, handler: async (ctx, args) => { const member = await ctx.db.get(args.memberId); if (!member) throw new Error("Team member not found"); await requireLocationManager(ctx, member.locationId); await ctx.db.patch(args.memberId, { name: args.name.trim() }); } });
export const deactivateTeamMember = mutation({ args: { memberId: v.id("teamMembers") }, handler: async (ctx, args) => { const member = await ctx.db.get(args.memberId); if (!member) throw new Error("Team member not found"); await requireLocationManager(ctx, member.locationId); await ctx.db.patch(args.memberId, { active: false }); } });
export const addTeamMember = mutation({ args: { locationId: v.id("locations"), email: v.string(), role: v.union(v.literal("staff"), v.literal("manager")) }, handler: async (ctx, args) => { await requireLocationAdmin(ctx, args.locationId); const user = await ctx.db.query("users").withIndex("email", q => q.eq("email", args.email.trim())).first(); if (!user) throw new Error("No account found for that email"); const existing = (await ctx.db.query("memberships").collect()).find(membership => membership.locationId === args.locationId && membership.userId === user._id); if (existing) { await ctx.db.patch(existing._id, { role: args.role }); return existing._id; } return await ctx.db.insert("memberships", { locationId: args.locationId, userId: user._id, role: args.role }); } });
export const removeTeamMember = mutation({ args: { membershipId: v.id("memberships") }, handler: async (ctx, args) => { const membership = await ctx.db.get(args.membershipId); if (!membership) throw new Error("Membership not found"); await requireLocationAdmin(ctx, membership.locationId); await ctx.db.delete(args.membershipId); } });
export const operations = query({ args: {}, handler: async (ctx) => { const userId = await signedIn(ctx); const memberships = await ctx.db.query("memberships").withIndex("by_user", q => q.eq("userId", userId)).collect(); const managerMemberships = memberships.filter(membership => membership.role === "admin" || membership.role === "manager"); if (!managerMemberships.length) throw new Error("Manager access required"); const locations = (await ctx.db.query("locations").collect()).filter(location => managerMemberships.some(membership => membership.locationId === location._id)); const result = []; for (const location of locations) { const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", q => q.eq("locationId", location._id)).collect(); const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", location._id)).collect(); result.push({ location, total: tasks.length + 3, complete: tasks.filter(t => t.status === "complete").length, outstanding: tasks.filter(t => t.status !== "complete").length, issues: issues.filter(i => i.status !== "resolved").length, latestIssue: issues.filter(i => i.status !== "resolved").sort((a, b) => b.createdAt - a.createdAt)[0] }); } return result; } });export const legacyCalendar = query({ args: { locationId: v.id("locations"), monthStart: v.number(), monthEnd: v.number() }, handler: async (ctx, args) => { await requireLocationAccess(ctx, args.locationId); const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const readings = await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const probes = await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const days: Record<string, { date: string; status: "green" | "amber" | "red"; readings: number; probes: number; issues: number }> = {}; for (const round of rounds) { const time = round.startedAt; if (time < args.monthStart || time > args.monthEnd) continue; const date = new Date(time).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].readings += readings.filter(item => item.roundId === round._id).length; } for (const probe of probes) { if (probe.createdAt < args.monthStart || probe.createdAt > args.monthEnd) continue; const date = new Date(probe.createdAt).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].probes++; if (probe.result === "fail") days[date].status = "amber"; } for (const issue of issues) { if (issue.createdAt < args.monthStart || issue.createdAt > args.monthEnd) continue; const date = new Date(issue.createdAt).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].issues++; if (issue.status !== "resolved") days[date].status = "red"; else if (days[date].status === "green") days[date].status = "amber"; } return Object.values(days); } });

export const calendar = query({
  args: { locationId: v.id("locations"), monthStart: v.number(), monthEnd: v.number() },
  handler: async (ctx, args) => {
    await requireLocationAccess(ctx, args.locationId);
    const location = await ctx.db.get(args.locationId);
    if (!location) return [];
    const timezone = location.timezone;
    const todayKey = localDateKey(Date.now(), timezone);
    const equipment = await ctx.db.query("equipment").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const openingQuestions = await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect();
    const closingQuestions = await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect();
    const securityQuestions = {
      AM: await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect(),
      PM: await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect(),
    };
    const organisation = await ctx.db.get(location.organisationId);
    const probeProducts = organisation ? (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", organisation._id)).collect()).filter(item => item.locationIds.includes(args.locationId)) : [];
    const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const readings = await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const probes = await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const openingResponses = await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect();
    const closingResponses = await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect();
    const securityResponses = {
      AM: await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect(),
      PM: await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect(),
    };
    const checklistSignOffs = {
      opening: await ctx.db.query("checklistSignOffs").withIndex("by_location_checklist_date", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect(),
      closing: await ctx.db.query("checklistSignOffs").withIndex("by_location_checklist_date", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect(),
    };
    const securitySignOffs = {
      AM: await ctx.db.query("securitySignOffs").withIndex("by_location_session_date", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect(),
      PM: await ctx.db.query("securitySignOffs").withIndex("by_location_session_date", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect(),
    };
    const additionalRequirements = await ctx.db.query("additionalRequirements").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const additionalCompletions = await ctx.db.query("additionalCompletions").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const wastage = await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const cleaningTasks = await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const cleaningCompletions = await ctx.db.query("cleaningCompletions").withIndex("by_location_date", q => q.eq("locationId", args.locationId)).collect();
    const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const days: Record<string, { date: string; status: "green" | "amber" | "red" | "grey"; readings: number; probes: number; issues: number }> = {};
    const start = new Date(args.monthStart);
    const end = new Date(args.monthEnd);
    const configAppliesOnDate = (item: any, dateKey: string) => localDateKey(item._creationTime, timezone) <= dateKey && (item.deactivatedAt === undefined || localDateKey(item.deactivatedAt, timezone) >= dateKey);
    for (let cursor = new Date(start.getFullYear(), start.getMonth(), start.getDate()); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
      const dateKey = localDateKey(cursor.getTime(), timezone);
      days[dateKey] = { date: dateKey, status: dateKey > todayKey ? "grey" : "red", readings: 0, probes: 0, issues: 0 };
    }
    for (const dateKey of Object.keys(days)) {
      if (dateKey > todayKey) continue;
      const dayEquipment = equipment.filter(item => configAppliesOnDate(item, dateKey));
      const dayOpeningQuestions = openingQuestions.filter(item => configAppliesOnDate(item, dateKey));
      const dayClosingQuestions = closingQuestions.filter(item => configAppliesOnDate(item, dateKey));
      const daySecurityQuestions = {
        AM: securityQuestions.AM.filter(item => configAppliesOnDate(item, dateKey)),
        PM: securityQuestions.PM.filter(item => configAppliesOnDate(item, dateKey)),
      };
      const dayProbeProducts = probeProducts.filter(item => configAppliesOnDate(item, dateKey));
      const dayCleaningTasks = cleaningTasks.filter(item => configAppliesOnDate(item, dateKey));
      const dayRounds = rounds.filter(item => localDateKey(item.startedAt, timezone) === dateKey);
      const dayReadings = readings.filter(item => localDateKey(item.createdAt, timezone) === dateKey && !item.voided);
      const dayProbes = probes.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayOpening = openingResponses.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayClosing = closingResponses.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayAmSecurity = securityResponses.AM.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayPmSecurity = securityResponses.PM.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const openingResponseIds = new Set(dayOpening.map(item => item.questionId));
      const closingResponseIds = new Set(dayClosing.map(item => item.questionId));
      const amSecurityResponseIds = new Set(dayAmSecurity.map(item => item.questionId));
      const pmSecurityResponseIds = new Set(dayPmSecurity.map(item => item.questionId));
      const openingComplete = dayOpeningQuestions.every(question => openingResponseIds.has(question._id)) && checklistSignOffs.opening.some(signOff => signOff.dateKey === dateKey);
      const closingComplete = dayClosingQuestions.every(question => closingResponseIds.has(question._id)) && checklistSignOffs.closing.some(signOff => signOff.dateKey === dateKey);
      const amSecurityComplete = daySecurityQuestions.AM.every(question => amSecurityResponseIds.has(question._id)) && securitySignOffs.AM.some(signOff => signOff.dateKey === dateKey);
      const pmSecurityComplete = daySecurityQuestions.PM.every(question => pmSecurityResponseIds.has(question._id)) && securitySignOffs.PM.some(signOff => signOff.dateKey === dateKey);
      const dueAdditionalRequirementIds = new Set(additionalCompletions.filter(completion => completion.scheduledDueAt !== undefined && localDateKey(completion.scheduledDueAt, timezone) === dateKey).map(completion => completion.requirementId));
      for (const requirement of additionalRequirements) if (requirement.active && configAppliesOnDate(requirement, dateKey) && requirement.nextDueAt !== undefined && localDateKey(requirement.nextDueAt, timezone) === dateKey) dueAdditionalRequirementIds.add(requirement._id);
      const additionalDue = dueAdditionalRequirementIds.size > 0;
      const additionalComplete = [...dueAdditionalRequirementIds].every(requirementId => additionalCompletions.some(completion => completion.requirementId === requirementId && completion.scheduledDueAt !== undefined && localDateKey(completion.scheduledDueAt, timezone) === dateKey && localDateKey(completion.completedAt, timezone) === dateKey));
      const dayWastage = wastage.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const weekday = localWeekday(new Date(`${dateKey}T12:00:00Z`).getTime(), timezone);
      const dueCleaning = dayCleaningTasks.filter(task => task.frequency === "after_use" || task.frequency === "daily" || (task.frequency === "weekly" && weekday === 1) || (task.frequency === "specific_days" && task.weekdays.includes(weekday)));
      const dayCleaning = cleaningCompletions.filter(item => item.dateKey === dateKey);
      const dayIssues = issues.filter(issue => localDateKey(issue.createdAt, timezone) === dateKey || (issue.createdAt < new Date(`${dateKey}T23:59:59Z`).getTime() && issue.status !== "resolved"));
      const failed = dayReadings.some(item => item.result === "fail") || dayProbes.some(item => item.result === "fail") || dayOpening.some(item => item.answer === "no") || dayClosing.some(item => item.answer === "no") || dayIssues.some(item => item.status !== "resolved");
      const complete = openingComplete && closingComplete && amSecurityComplete && pmSecurityComplete && (!additionalDue || additionalComplete) && ["AM", "PM"].every(session => { const round = dayRounds.find(item => item.session === session && item.completedAt); return !!round && dayReadings.filter(reading => reading.roundId === round._id).length >= dayEquipment.length; }) && (dayProbeProducts.length === 0 || dayProbeProducts.every(product => dayProbes.some(probe => probe.product === product.name))) && dayWastage.length > 0 && dayCleaning.length >= dueCleaning.length;
      const day = days[dateKey];
      day.readings = dayReadings.length;
      day.probes = dayProbes.length;
      day.issues = dayIssues.length;
      day.status = complete ? (failed ? "amber" : "green") : "red";
    }
    return Object.values(days);
  },
});

export const archive = query({ args: { locationId: v.id("locations"), start: v.number(), end: v.number() }, handler: async (ctx, args) => { await requireLocationAccess(ctx, args.locationId); const readings = (await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const probes = await Promise.all((await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end).map(async item => ({ ...item, teamMemberName: item.teamMemberId ? (await ctx.db.get(item.teamMemberId))?.name : undefined }))); const issues = (await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); const issueUpdates = await ctx.db.query("issueUpdates").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const issuesWithUpdates = await Promise.all(issues.map(async issue => ({ ...issue, createdByName: (await ctx.db.get(issue.createdBy))?.name ?? "Staff member", resolvedByName: issue.resolvedBy ? (await ctx.db.get(issue.resolvedBy))?.name ?? "Manager" : undefined, updates: await Promise.all(issueUpdates.filter(update => update.issueId === issue._id).sort((a, b) => a.createdAt - b.createdAt).map(async update => ({ ...update, createdByName: (await ctx.db.get(update.createdBy))?.name ?? "Staff member" }))) }))); const location = await ctx.db.get(args.locationId); const timezone = location?.timezone ?? "Europe/London"; const checklistQuestions = { opening: await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect(), closing: await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect() }; const enrichChecklistResponses = async (checklist: "opening" | "closing") => { const responses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", checklist)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); return Promise.all(responses.map(async response => ({ ...response, question: checklistQuestions[checklist].find(item => item._id === response.questionId)?.question ?? "Checklist task", teamMemberName: response.teamMemberId ? (await ctx.db.get(response.teamMemberId))?.name : (await ctx.db.get(response.createdBy))?.name }))); }; const questions = { opening: await enrichChecklistResponses("opening"), closing: await enrichChecklistResponses("closing") }; const securityResponses = { AM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end), PM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end) }; const cleaningTasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(task => task.active); const cleaningCompletions = (await Promise.all(cleaningTasks.map(task => ctx.db.query("cleaningCompletions").withIndex("by_task", q => q.eq("taskId", task._id)).collect()))).flat().filter(item => item.completedAt >= args.start && item.completedAt <= args.end); const cleaningCompletionsWithNames = await Promise.all(cleaningCompletions.map(async completion => ({ ...completion, teamMemberName: completion.teamMemberId ? (await ctx.db.get(completion.teamMemberId))?.name : undefined }))); const wastageRecords = await Promise.all((await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end).map(async item => ({ ...item, teamMemberName: item.teamMemberId ? (await ctx.db.get(item.teamMemberId))?.name : undefined }))); return { readings, rounds: rounds.filter(round => round.startedAt >= args.start && round.startedAt <= args.end), probes, issues: issuesWithUpdates, questions, securityResponses, wastageRecords, cleaningTasks, cleaningCompletions: cleaningCompletionsWithNames }; } });

export const startRound = mutation({ args: { locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } return await ctx.db.insert("temperatureRounds", { ...args, startedAt: Date.now(), createdBy: userId }); } });
export const recordTemperature = mutation({ args: { roundId: v.id("temperatureRounds"), locationId: v.id("locations"), equipmentId: v.id("equipment"), temperature: v.number(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); const [round, equipment] = await Promise.all([ctx.db.get(args.roundId), ctx.db.get(args.equipmentId)]); if (!round || round.locationId !== args.locationId) throw new Error("Round does not belong to this location"); if (!equipment || equipment.locationId !== args.locationId) throw new Error("Equipment does not belong to this location"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } const preferred = equipment?.preferredTemperature ?? 5; const maximum = equipment?.maximumTemperature ?? 8; const result = args.temperature > maximum ? "fail" : args.temperature > preferred ? "within_limit" : "normal"; const readingId = await ctx.db.insert("temperatureReadings", { ...args, result, createdAt: Date.now(), createdBy: userId, voided: false }); let issueId = null; if (result === "fail") { issueId = await ctx.db.insert("issues", { locationId: args.locationId, category: "Temperature", title: `${equipment?.name ?? "Fridge"} requires action`, description: `Recorded at ${args.temperature}°C. The configured maximum is ${maximum}°C.`, originalReading: `${args.temperature}°C`, status: "open", createdAt: Date.now(), createdBy: userId, teamMemberId: args.teamMemberId }); } return { readingId, issueId }; } });
export const completeRound = mutation({ args: { roundId: v.id("temperatureRounds"), locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); const round = await ctx.db.get(args.roundId); if (!round || round.locationId !== args.locationId) throw new Error("Round does not belong to this location"); if (round.session !== args.session) throw new Error("Round session does not match"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } await ctx.db.patch(args.roundId, { completedAt: Date.now(), ...(args.teamMemberId ? { teamMemberId: args.teamMemberId } : {}) }); const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const sessionTask = tasks.find(item => item.session === args.session); if (sessionTask) await ctx.db.patch(sessionTask._id, { status: "complete", completedAt: Date.now(), completedBy: userId }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "temperature_round_completed", detail: `${args.session} temperature round completed`, createdAt: Date.now() }); } });
export const recordFoodCheck = mutation({ args: { locationId: v.id("locations"), product: v.string(), quantity: v.optional(v.string()), temperature: v.number(), action: v.optional(v.string()), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } if (!args.quantity?.trim()) throw new Error("Quantity is required"); const location = await ctx.db.get(args.locationId); if (!location) throw new Error("Location not found"); const configuredProduct = (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", location.organisationId)).collect()).find(product => product.active && product.name === args.product && product.locationIds.includes(args.locationId)); if (!configuredProduct) throw new Error("No active probe product is configured for this location"); const now = Date.now(); const result = args.temperature >= configuredProduct.minimumTemperature ? "pass" : "fail"; const checkId = await ctx.db.insert("foodChecks", { ...args, result, createdAt: now, createdBy: userId }); let issueId = null; if (result === "fail") { issueId = await ctx.db.insert("issues", { locationId: args.locationId, category: "Probe", title: `${args.product} probe below minimum`, description: `Recorded at ${args.temperature}°C for quantity ${args.quantity}. Configured minimum is ${configuredProduct.minimumTemperature}°C.`, originalReading: `${args.temperature}°C`, status: "open", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId, action: args.action }); if (args.action?.trim()) await ctx.db.insert("issueUpdates", { issueId, locationId: args.locationId, updateType: "immediate_action", note: args.action.trim(), status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } return { checkId, issueId }; } });export const recordProbeRecheck = mutation({ args: { issueId: v.id("issues"), temperature: v.number(), teamMemberId: v.id("teamMembers") }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const issue = await ctx.db.get(args.issueId); if (!issue) throw new Error("Issue not found"); if (issue.category !== "Probe") throw new Error("Issue is not a probe issue"); if (issue.status === "resolved") throw new Error("Probe issue is already resolved"); await requireLocationAccess(ctx, issue.locationId); const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== issue.locationId) throw new Error("Team member does not belong to this location"); const productSuffix = " probe below minimum"; if (!issue.title.endsWith(productSuffix)) throw new Error("Probe issue does not contain its original product"); const originalProduct = issue.title.slice(0, -productSuffix.length).trim(); if (!originalProduct) throw new Error("Probe issue does not contain its original product"); const location = await ctx.db.get(issue.locationId); if (!location) throw new Error("Location not found"); const configuredProduct = (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", location.organisationId)).collect()).find(product => product.active && product.name === originalProduct && product.locationIds.includes(issue.locationId)); if (!configuredProduct) throw new Error("No active probe product is configured for this location"); const now = Date.now(); const result = args.temperature >= configuredProduct.minimumTemperature ? "pass" : "fail"; await ctx.db.insert("rechecks", { issueId: args.issueId, locationId: issue.locationId, temperature: args.temperature, result, createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); if (result === "pass") { await ctx.db.patch(args.issueId, { status: "resolved", resolvedAt: now, resolvedBy: userId, resolutionNote: "Rechecked at " + args.temperature + "°C" }); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "resolution", note: "Rechecked at " + args.temperature + "°C", status: "resolved", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } else { await ctx.db.patch(args.issueId, { status: "monitoring" }); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "further_action", note: "Recheck remained below configured minimum of " + configuredProduct.minimumTemperature + "°C at " + args.temperature + "°C", status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } return { result }; } });
export const recordWastage = mutation({ args: { locationId: v.id("locations"), itemId: v.optional(v.id("wastageItems")), quantity: v.optional(v.string()), notes: v.optional(v.string()), noWaste: v.boolean(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); if (!args.noWaste && (!args.itemId || !args.quantity?.trim())) throw new Error("Select a wasted item and enter its quantity"); const item = args.itemId ? await ctx.db.get(args.itemId) : null; if (args.itemId && (!item || item.locationId !== args.locationId)) throw new Error("Wastage item does not belong to this location"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } return await ctx.db.insert("wastageRecords", { locationId: args.locationId, itemId: args.itemId, itemName: item?.name, quantity: args.noWaste ? undefined : args.quantity, notes: args.notes, noWaste: args.noWaste, createdAt: Date.now(), createdBy: userId, teamMemberId: args.teamMemberId }); } });
