export const saveChecklistResponse = mutation({ args: { locationId: v.id("locations"), checklist: v.union(v.literal("opening"), v.literal("closing")), questionId: v.id("checklistQuestions"), answer: v.union(v.literal("yes"), v.literal("no"), v.literal("na")), problem: v.optional(v.string()), action: v.optional(v.string()), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); const question = await ctx.db.get(args.questionId); if (!question || question.locationId !== args.locationId) throw new Error("Checklist question does not belong to this location"); if (question.checklist !== args.checklist) throw new Error("Checklist question does not match this checklist"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } if (args.answer === "no" && !args.action?.trim()) throw new Error("A corrective action is required"); const location = await ctx.db.get(args.locationId); const timezone = location?.timezone ?? "Europe/London"; const dateKey = localDateKey(Date.now(), timezone); const existingResponses = await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", args.checklist)).collect(); if (existingResponses.some(response => response.questionId === args.questionId && localDateKey(response.createdAt, timezone) === dateKey)) throw new Error("Checklist question already answered today"); const responseId = await ctx.db.insert("checklistResponses", { ...args, createdAt: Date.now(), createdBy: userId }); if (args.answer === "no") { const now = Date.now(); const issueId = await ctx.db.insert("issues", { locationId: args.locationId, category: "Food safety", title: args.checklist + " checklist: " + question.question, description: args.problem?.trim() || question.question, status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId, action: args.action?.trim() }); await ctx.db.insert("issueUpdates", { issueId, locationId: args.locationId, updateType: "immediate_action", note: args.action!.trim(), status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } return responseId; } });
