export const signOffChecklist = mutation({ args: { locationId: v.id("locations"), checklist: v.union(v.literal("opening"), v.literal("closing")), teamMemberId: v.id("teamMembers") }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } const location = await ctx.db.get(args.locationId); const now = Date.now(); const timezone = location?.timezone ?? "Europe/London"; const dateKey = localDateKey(now, timezone); const existingSignOff = await ctx.db.query("checklistSignOffs").withIndex("by_location_checklist_date", q => q.eq("locationId", args.locationId).eq("checklist", args.checklist).eq("dateKey", dateKey)).collect(); if (existingSignOff.length) throw new Error("Checklist is already signed off for today"); const questions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", args.checklist)).collect()).filter(question => question.active); if (!questions.length) throw new Error("No active checklist questions exist for this location"); const responses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", args.checklist)).collect()).filter(response => localDateKey(response.createdAt, timezone) === dateKey); const responseQuestionIds = new Set(responses.map(response => response.questionId)); if (questions.some(question => !responseQuestionIds.has(question._id))) throw new Error("Every active checklist question must have a response today"); await ctx.db.insert("checklistSignOffs", { locationId: args.locationId, checklist: args.checklist, dateKey, completedAt: now, completedBy: userId, teamMemberId: args.teamMemberId }); } });
export const signOffSecurity = mutation({ args: { locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), teamMemberId: v.id("teamMembers") }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } const location = await ctx.db.get(args.locationId); const now = Date.now(); const timezone = location?.timezone ?? "Europe/London"; const dateKey = localDateKey(now, timezone); const existingSignOff = await ctx.db.query("securitySignOffs").withIndex("by_location_session_date", q => q.eq("locationId", args.locationId).eq("session", args.session).eq("dateKey", dateKey)).collect(); if (existingSignOff.length) throw new Error("Security session is already signed off for today"); const questions = (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", args.session)).collect()).filter(question => question.active); if (!questions.length) throw new Error("No active security questions exist for this location"); const responses = (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", args.session)).collect()).filter(response => localDateKey(response.createdAt, timezone) === dateKey); const responseQuestionIds = new Set(responses.map(response => response.questionId)); if (questions.some(question => !responseQuestionIds.has(question._id))) throw new Error("Every active security question must have a response today"); await ctx.db.insert("securitySignOffs", { locationId: args.locationId, session: args.session, dateKey, completedAt: now, completedBy: userId, teamMemberId: args.teamMemberId }); } });
export const addEquipment = mutation({ args: { locationId: v.id("locations"), name: v.optional(v.string()), type: v.optional(v.string()), preferredTemperature: v.optional(v.number()), maximumTemperature: v.optional(v.number()) }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); await requireLocationManager(ctx, args.locationId); const equipment = await ctx.db.query("equipment").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const active = equipment.filter(item => item.active); const id = await ctx.db.insert("equipment", { locationId: args.locationId, name: args.name?.trim() || `Fridge ${active.length + 1}`, type: args.type || "Food fridge", preferredTemperature: args.preferredTemperature ?? 5, maximumTemperature: args.maximumTemperature ?? 8, order: equipment.length, active: true }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "equipment_added", detail: `Fridge ${active.length + 1} added`, createdAt: Date.now() }); return id; } });
export const updateEquipmentLimits = mutation({ args: { equipmentId: v.id("equipment"), preferredTemperature: v.number(), maximumTemperature: v.number() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const equipment = await ctx.db.get(args.equipmentId); if (!equipment) throw new Error("Equipment not found"); await requireLocationManager(ctx, equipment.locationId); await ctx.db.patch(args.equipmentId, { preferredTemperature: args.preferredTemperature, maximumTemperature: args.maximumTemperature }); await ctx.db.insert("auditEvents", { locationId: equipment.locationId, userId, type: "equipment_limits_updated", detail: `${equipment.name}: preferred ${args.preferredTemperature}°C, maximum ${args.maximumTemperature}°C`, createdAt: Date.now() }); } });
export const setFridgeCount = mutation({ args: { locationId: v.id("locations"), count: v.number() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); await requireLocationManager(ctx, args.locationId); const items = await ctx.db.query("equipment").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const active = items.filter(item => item.active).sort((a, b) => a.order - b.order); for (let index = 0; index < active.length; index++) { const item = active[index]; if (index < args.count) await ctx.db.patch(item._id, { name: `Fridge ${index + 1}`, active: true }); else await ctx.db.patch(item._id, { name: `Fridge ${index + 1}`, active: false, deactivatedAt: Date.now() }); } for (let index = active.length; index < args.count; index++) await ctx.db.insert("equipment", { locationId: args.locationId, name: `Fridge ${index + 1}`, type: "Food fridge", preferredTemperature: 5, maximumTemperature: 8, order: index, active: true }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "fridge_count_changed", detail: `Active fridges set to ${args.count}`, createdAt: Date.now() }); } });
export const addProbeProduct = mutation({ args: { organisationId: v.id("organisations"), name: v.string(), minimumTemperature: v.number(), holdMinutes: v.number(), locationIds: v.array(v.id("locations")) }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); if (!args.locationIds.length) throw new Error("Manager access required"); for (const locationId of args.locationIds) await requireLocationManager(ctx, locationId); const id = await ctx.db.insert("probeProducts", { ...args, active: true }); await ctx.db.insert("auditEvents", { userId, type: "probe_product_added", detail: args.name, createdAt: Date.now() }); return id; } });
export const addChecklistQuestion = mutation({ args: { locationId: v.id("locations"), checklist: v.union(v.literal("opening"), v.literal("closing")), question: v.string() }, handler: async (ctx, args) => { await requireLocationManager(ctx, args.locationId); const questions = await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", args.checklist)).collect(); return await ctx.db.insert("checklistQuestions", { ...args, order: questions.length, active: true }); } });
export const updateChecklistQuestion = mutation({ args: { questionId: v.id("checklistQuestions"), question: v.string() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const current = await ctx.db.get(args.questionId); if (!current) throw new Error("Question not found"); await requireLocationManager(ctx, current.locationId); await ctx.db.patch(args.questionId, { question: args.question.trim() }); await ctx.db.insert("auditEvents", { locationId: current.locationId, userId, type: "checklist_question_updated", detail: args.question, createdAt: Date.now() }); } });
export const reorderChecklistQuestion = mutation({ args: { questionId: v.id("checklistQuestions"), direction: v.union(v.literal("up"), v.literal("down")) }, handler: async (ctx, args) => { const current = await ctx.db.get(args.questionId); if (!current) throw new Error("Question not found"); await requireLocationManager(ctx, current.locationId); const items = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", current.locationId).eq("checklist", current.checklist)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order); const index = items.findIndex(item => item._id === args.questionId); const target = args.direction === "up" ? index - 1 : index + 1; if (index < 0 || !items[target]) return; await ctx.db.patch(items[index]._id, { order: items[target].order }); await ctx.db.patch(items[target]._id, { order: items[index].order }); } });
export const deleteChecklistQuestion = mutation({ args: { questionId: v.id("checklistQuestions") }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const question = await ctx.db.get(args.questionId); if (!question) throw new Error("Question not found"); await requireLocationManager(ctx, question.locationId); await ctx.db.patch(args.questionId, { active: false, deactivatedAt: Date.now() }); await ctx.db.insert("auditEvents", { locationId: question.locationId, userId, type: "checklist_question_deactivated", detail: question.question, createdAt: Date.now() }); } });
export const addCleaningTask = mutation({ args: { locationId: v.id("locations"), name: v.string(), frequency: v.union(v.literal("after_use"), v.literal("daily"), v.literal("weekly"), v.literal("specific_days")), weekdays: v.array(v.number()) }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); await requireLocationManager(ctx, args.locationId); const tasks = await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const id = await ctx.db.insert("cleaningTasks", { ...args, name: args.name.trim(), order: tasks.length, active: true }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "cleaning_task_added", detail: args.name, createdAt: Date.now() }); return id; } });
export const updateCleaningTask = mutation({ args: { taskId: v.id("cleaningTasks"), name: v.string(), frequency: v.union(v.literal("after_use"), v.literal("daily"), v.literal("weekly"), v.literal("specific_days")), weekdays: v.array(v.number()) }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const task = await ctx.db.get(args.taskId); if (!task) throw new Error("Cleaning task not found"); await requireLocationManager(ctx, task.locationId); await ctx.db.patch(args.taskId, { name: args.name.trim(), frequency: args.frequency, weekdays: args.weekdays }); await ctx.db.insert("auditEvents", { locationId: task.locationId, userId, type: "cleaning_task_updated", detail: args.name, createdAt: Date.now() }); } });
export const deleteCleaningTask = mutation({ args: { taskId: v.id("cleaningTasks") }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const task = await ctx.db.get(args.taskId); if (!task) throw new Error("Cleaning task not found"); await requireLocationManager(ctx, task.locationId); await ctx.db.patch(args.taskId, { active: false, deactivatedAt: Date.now() }); await ctx.db.insert("auditEvents", { locationId: task.locationId, userId, type: "cleaning_task_deactivated", detail: task.name, createdAt: Date.now() }); } });
export const reorderCleaningTask = mutation({ args: { taskId: v.id("cleaningTasks"), direction: v.union(v.literal("up"), v.literal("down")) }, handler: async (ctx, args) => { const task = await ctx.db.get(args.taskId); if (!task) throw new Error("Cleaning task not found"); await requireLocationManager(ctx, task.locationId); const tasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", task.locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order); const index = tasks.findIndex(item => item._id === args.taskId); const target = args.direction === "up" ? index - 1 : index + 1; if (index < 0 || !tasks[target]) return; await ctx.db.patch(tasks[index]._id, { order: tasks[target].order }); await ctx.db.patch(tasks[target]._id, { order: tasks[index].order }); } });
export const completeCleaningTask = mutation({ args: { locationId: v.id("locations"), taskId: v.id("cleaningTasks"), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); const task = await ctx.db.get(args.taskId); if (!task || task.locationId !== args.locationId) throw new Error("Cleaning task does not belong to this location"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } const location = await ctx.db.get(args.locationId); const dateKey = localDateKey(Date.now(), location?.timezone ?? "Europe/London"); const existing = await ctx.db.query("cleaningCompletions").withIndex("by_location_date", q => q.eq("locationId", args.locationId).eq("dateKey", dateKey)).collect(); if (existing.some(item => item.taskId === args.taskId)) return; return await ctx.db.insert("cleaningCompletions", { locationId: args.locationId, taskId: args.taskId, dateKey, completedAt: Date.now(), completedBy: userId, teamMemberId: args.teamMemberId }); } });
export const addSecurityQuestion = mutation({ args: { locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), question: v.string() }, handler: async (ctx, args) => { await requireLocationManager(ctx, args.locationId); const questions = await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", args.session)).collect(); return await ctx.db.insert("securityQuestions", { locationId: args.locationId, session: args.session, question: args.question.trim(), order: questions.length, active: true }); } });
export const updateSecurityQuestion = mutation({ args: { questionId: v.id("securityQuestions"), question: v.string() }, handler: async (ctx, args) => { const question = await ctx.db.get(args.questionId); if (!question) throw new Error("Question not found"); await requireLocationManager(ctx, question.locationId); await ctx.db.patch(args.questionId, { question: args.question.trim() }); } });
export const deleteSecurityQuestion = mutation({ args: { questionId: v.id("securityQuestions") }, handler: async (ctx, args) => { const question = await ctx.db.get(args.questionId); if (!question) throw new Error("Question not found"); await requireLocationManager(ctx, question.locationId); await ctx.db.patch(args.questionId, { active: false, deactivatedAt: Date.now() }); } });
export const addWastageItem = mutation({ args: { locationId: v.id("locations"), name: v.string() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); await requireLocationManager(ctx, args.locationId); const items = await ctx.db.query("wastageItems").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const id = await ctx.db.insert("wastageItems", { locationId: args.locationId, name: args.name.trim(), order: items.length, active: true }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "wastage_item_added", detail: args.name, createdAt: Date.now() }); return id; } });
export const updateWastageItem = mutation({ args: { itemId: v.id("wastageItems"), name: v.string() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const item = await ctx.db.get(args.itemId); if (!item) throw new Error("Wastage item not found"); await requireLocationManager(ctx, item.locationId); await ctx.db.patch(args.itemId, { name: args.name.trim() }); await ctx.db.insert("auditEvents", { locationId: item.locationId, userId, type: "wastage_item_updated", detail: args.name, createdAt: Date.now() }); } });
export const reorderWastageItem = mutation({ args: { itemId: v.id("wastageItems"), direction: v.union(v.literal("up"), v.literal("down")) }, handler: async (ctx, args) => { const current = await ctx.db.get(args.itemId); if (!current) throw new Error("Wastage item not found"); await requireLocationManager(ctx, current.locationId); const items = (await ctx.db.query("wastageItems").withIndex("by_location", q => q.eq("locationId", current.locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order); const index = items.findIndex(item => item._id === args.itemId); const target = args.direction === "up" ? index - 1 : index + 1; if (index < 0 || !items[target]) return; await ctx.db.patch(items[index]._id, { order: items[target].order }); await ctx.db.patch(items[target]._id, { order: items[index].order }); } });
export const updateProbeProduct = mutation({ args: { productId: v.id("probeProducts"), name: v.string(), minimumTemperature: v.number(), holdMinutes: v.number() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const product = await ctx.db.get(args.productId); if (!product) throw new Error("Probe product not found"); if (!product.locationIds.length) throw new Error("Manager access required"); for (const locationId of product.locationIds) await requireLocationManager(ctx, locationId); await ctx.db.patch(args.productId, { name: args.name.trim(), minimumTemperature: args.minimumTemperature, holdMinutes: args.holdMinutes }); await ctx.db.insert("auditEvents", { userId, type: "probe_product_updated", detail: args.name, createdAt: Date.now() }); } });
export const generateTrainingUploadUrl = mutation({ args: {}, handler: async (ctx) => { const userId = await requireSignedIn(ctx); const memberships = await ctx.db.query("memberships").withIndex("by_user", q => q.eq("userId", userId)).collect(); const managerMembership = memberships.find(membership => membership.role === "manager" || membership.role === "admin"); if (!managerMembership) throw new Error("Manager access required"); await requireLocationManager(ctx, managerMembership.locationId); return await ctx.storage.generateUploadUrl(); } });
export const attachTrainingDocument = mutation({ args: { requirementId: v.id("trainingRequirements"), storageId: v.id("_storage"), documentName: v.string() }, handler: async (ctx, args) => { const requirement = await ctx.db.get(args.requirementId); if (!requirement) throw new Error("Training requirement not found"); await requireLocationManager(ctx, requirement.locationId); if (requirement.documentStorageId) await ctx.storage.delete(requirement.documentStorageId); await ctx.db.patch(args.requirementId, { documentStorageId: args.storageId, documentName: args.documentName }); } });
export const removeTrainingDocument = mutation({ args: { requirementId: v.id("trainingRequirements") }, handler: async (ctx, args) => { const requirement = await ctx.db.get(args.requirementId); if (!requirement) throw new Error("Training requirement not found"); await requireLocationManager(ctx, requirement.locationId); if (requirement.documentStorageId) await ctx.storage.delete(requirement.documentStorageId); await ctx.db.patch(args.requirementId, { documentStorageId: undefined, documentName: undefined }); } });
export const addTrainingRequirement = mutation({ args: { locationId: v.id("locations"), title: v.string() }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); await requireLocationManager(ctx, args.locationId); const existing = await ctx.db.query("trainingRequirements").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); return await ctx.db.insert("trainingRequirements", { locationId: args.locationId, title: args.title.trim(), active: true, order: existing.length }); } });
export const updateTrainingRequirement = mutation({ args: { requirementId: v.id("trainingRequirements"), title: v.string() }, handler: async (ctx, args) => { const requirement = await ctx.db.get(args.requirementId); if (!requirement) throw new Error("Training requirement not found"); await requireLocationManager(ctx, requirement.locationId); await ctx.db.patch(args.requirementId, { title: args.title.trim() }); } });
export const deleteTrainingRequirement = mutation({ args: { requirementId: v.id("trainingRequirements") }, handler: async (ctx, args) => { const requirement = await ctx.db.get(args.requirementId); if (!requirement) throw new Error("Training requirement not found"); await requireLocationManager(ctx, requirement.locationId); await ctx.db.patch(args.requirementId, { active: false }); } });
export const reorderTrainingRequirement = mutation({ args: { requirementId: v.id("trainingRequirements"), direction: v.union(v.literal("up"), v.literal("down")) }, handler: async (ctx, args) => { const current = await ctx.db.get(args.requirementId); if (!current) throw new Error("Training requirement not found"); await requireLocationManager(ctx, current.locationId); const items = (await ctx.db.query("trainingRequirements").withIndex("by_location", q => q.eq("locationId", current.locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order); const index = items.findIndex(item => item._id === args.requirementId); const target = args.direction === "up" ? index - 1 : index + 1; if (index < 0 || !items[target]) return; await ctx.db.patch(items[index]._id, { order: items[target].order }); await ctx.db.patch(items[target]._id, { order: items[index].order }); } });
export const completeTrainingRequirement = mutation({ args: { locationId: v.id("locations"), requirementId: v.id("trainingRequirements"), teamMemberId: v.id("teamMembers") }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await requireLocationAccess(ctx, args.locationId); const requirement = await ctx.db.get(args.requirementId); if (!requirement || requirement.locationId !== args.locationId) throw new Error("Training requirement does not belong to this location"); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== args.locationId) throw new Error("Team member does not belong to this location"); } const existing = (await ctx.db.query("trainingCompletions").withIndex("by_requirement", q => q.eq("requirementId", args.requirementId)).collect()).find(item => item.teamMemberId === args.teamMemberId); if (existing) return existing._id; return await ctx.db.insert("trainingCompletions", { locationId: args.locationId, requirementId: args.requirementId, teamMemberId: args.teamMemberId, completedAt: Date.now(), completedBy: userId }); } });
export const deleteProbeProduct = mutation({ args: { productId: v.id("probeProducts") }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const product = await ctx.db.get(args.productId); if (!product) throw new Error("Probe product not found"); if (!product.locationIds.length) throw new Error("Manager access required"); for (const locationId of product.locationIds) await requireLocationManager(ctx, locationId); await ctx.db.patch(args.productId, { active: false, deactivatedAt: Date.now() }); await ctx.db.insert("auditEvents", { userId, type: "probe_product_deactivated", detail: product.name, createdAt: Date.now() }); } });
export const deleteWastageItem = mutation({ args: { itemId: v.id("wastageItems") }, handler: async (ctx, args) => { const userId = await requireSignedIn(ctx); const item = await ctx.db.get(args.itemId); if (!item) throw new Error("Wastage item not found"); await requireLocationManager(ctx, item.locationId); await ctx.db.patch(args.itemId, { active: false }); await ctx.db.insert("auditEvents", { locationId: item.locationId, userId, type: "wastage_item_deactivated", detail: item.name, createdAt: Date.now() }); } });
export const addIssueUpdate = mutation({ args: { issueId: v.id("issues"), note: v.string(), status: v.union(v.literal("open"), v.literal("monitoring"), v.literal("resolved")), updateType: v.union(v.literal("further_action"), v.literal("resolution"), v.literal("status_change")), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const issue = await ctx.db.get(args.issueId); if (!issue) throw new Error("Issue not found"); await requireLocationAccess(ctx, issue.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== issue.locationId) throw new Error("Team member does not belong to this location"); } const now = Date.now(); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: args.updateType, note: args.note.trim(), status: args.status, createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); await ctx.db.patch(args.issueId, { status: args.status, ...(args.status === "resolved" ? { resolvedAt: now, resolvedBy: userId, resolutionNote: args.note.trim() } : {}) }); } });
export const addIssueAction = mutation({ args: { issueId: v.id("issues"), action: v.string(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const issue = await ctx.db.get(args.issueId); if (!issue) throw new Error("Issue not found"); await requireLocationAccess(ctx, issue.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== issue.locationId) throw new Error("Team member does not belong to this location"); } const now = Date.now(); await ctx.db.patch(args.issueId, { action: args.action, status: "monitoring" }); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "immediate_action", note: args.action.trim(), status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); await ctx.db.insert("auditEvents", { locationId: issue.locationId, userId, type: "corrective_action_added", detail: args.action, createdAt: now }); } });
export const addRecheck = mutation({ args: { issueId: v.id("issues"), temperature: v.number(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const issue = await ctx.db.get(args.issueId); if (!issue) throw new Error("Issue not found"); await requireLocationAccess(ctx, issue.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== issue.locationId) throw new Error("Team member does not belong to this location"); } const now = Date.now(); const result = args.temperature <= 8 ? "pass" : "fail"; await ctx.db.insert("rechecks", { issueId: args.issueId, locationId: issue.locationId, temperature: args.temperature, teamMemberId: args.teamMemberId, result, createdAt: now, createdBy: userId }); if (result === "pass") { await ctx.db.patch(args.issueId, { status: "resolved", resolvedAt: now, resolvedBy: userId, resolutionNote: `Rechecked at ${args.temperature}°C` }); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "resolution", note: `Rechecked at ${args.temperature}°C`, status: "resolved", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } else { await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "further_action", note: `Recheck remained out of range at ${args.temperature}°C`, status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } } });
export const resolveIssue = mutation({ args: { issueId: v.id("issues"), action: v.string(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const issue = await ctx.db.get(args.issueId); if (!issue) throw new Error("Issue not found"); await requireLocationAccess(ctx, issue.locationId); if (args.teamMemberId) { const teamMember = await ctx.db.get(args.teamMemberId); if (!teamMember || teamMember.locationId !== issue.locationId) throw new Error("Team member does not belong to this location"); } const now = Date.now(); await ctx.db.patch(args.issueId, { action: args.action, status: "resolved", resolvedAt: now, resolvedBy: userId, resolutionNote: args.action }); await ctx.db.insert("issueUpdates", { issueId: args.issueId, locationId: issue.locationId, updateType: "resolution", note: args.action, status: "resolved", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); await ctx.db.insert("auditEvents", { locationId: issue.locationId, userId, type: "issue_resolved", detail: args.action, createdAt: Date.now() }); } });